using GalgameManager.Contracts.Services;using GalgameManager.Models;using GalgameManager.Services;using GalgameManager.WinApp.Base.Models;namespace GalgameManager.Helpers;public static class PluginInvokeHelper{    public static void Invoke (PluginInfo plugin, Action action, IInfoService infoService)    {        try        {            using IDisposable scope = EnterPluginXamlScope(plugin);            action();        }        catch (Exception ex)        {            infoService.PluginEvent(plugin, ex);        }    }    public static T? Invoke<T> (PluginInfo plugin, Func<T> func, IInfoService infoService)    {        try        {            using IDisposable scope = EnterPluginXamlScope(plugin);            return func();        }        catch (Exception ex)        {            infoService.PluginEvent(plugin, ex);        }        return default;    }    public static async Task InvokeAsync (PluginInfo plugin, Func<Task> func, IInfoService infoService)    {        try        {            using IDisposable scope = EnterPluginXamlScope(plugin);            await func();        }        catch (Exception ex)        {            infoService.PluginEvent(plugin, ex);        }    }    public static async Task<T?> InvokeAsync<T> (PluginInfo plugin, Func<Task<T>> func, IInfoService infoService)    {        try        {            using IDisposable scope = EnterPluginXamlScope(plugin);            return await func();        }        catch (Exception ex)        {            infoService.PluginEvent(plugin, ex);        }        return default;    }    /// <summary>    /// XAML解析器在解析UI的时候，会把不同插件相同命名空间的同名空间混淆为一个。<br/>    /// 例如插件A和B都拥有一个namespace1:control1的控件，那么在解析XAML时就会控件串台 <br/>    /// 因此，我们在调用插件前先清空XAML缓存，临时挂在上对应插件的XAML资源，调用后再恢复原样    /// </summary>    /// <param name="pluginInfo"></param>    /// <returns></returns>    private static IDisposable EnterPluginXamlScope(PluginInfo pluginInfo)    {        PluginX? plugin = App.GetService<IPluginService>()            .GetAllPluginsAsync().GetAwaiter().GetResult()            .FirstOrDefault(p => p.Id == pluginInfo.Id && p.Plugin is not null);        return plugin?.Plugin is null            ? NullScope.Instance            : PluginXamlHost.EnterScope(plugin.Plugin.GetType().Assembly);    }    private sealed class NullScope : IDisposable    {        public static readonly NullScope Instance = new();        public void Dispose() { }    }}